// Firebase Messaging Service Worker
// Config is injected at build/dev time by the custom Vite plugin in vite.config.js.
// Do NOT edit this file directly — edit the source template at
// src/firebase-messaging-sw-template.js instead.

const config = __FIREBASE_CONFIG__

if (config && config.apiKey) {
  importScripts('https://www.gstatic.com/firebasejs/10.12.2/firebase-app-compat.js')
  importScripts('https://www.gstatic.com/firebasejs/10.12.2/firebase-messaging-compat.js')

  firebase.initializeApp(config)

  const messaging = firebase.messaging()

  // Handle background push messages (app not in foreground).
  messaging.onBackgroundMessage((payload) => {
    const { title, body, icon } = payload.notification ?? {}

    self.registration.showNotification(title ?? 'Notifikasi Baru', {
      body: body ?? '',
      icon: icon ?? '/favicon.ico',
      badge: '/favicon.ico',
      data: payload.data,
    })
  })
}

self.addEventListener('notificationclick', (event) => {
  event.notification.close()

  const url = event.notification.data?.url ?? '/'

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
      for (const client of windowClients) {
        if (client.url === url && 'focus' in client) {
          return client.focus()
        }
      }
      if (clients.openWindow) {
        return clients.openWindow(url)
      }
    })
  )
})
